/bin/zsh -lc "gzip -t releases/boot-snapshot/omarchy-apps-ready-98235fbe8cc4.snap.gz && gzip -dc releases/boot-snapshot/omarchy-apps-ready-98235fbe8cc4.snap.gz | python3 -c '
import sys,struct,hashlib
h=hashlib.sha256(); total=0
def readn(n):
 global total
 out=bytearray()
 while len(out)<n:
  b=sys.stdin.buffer.read(min(1048576,n-len(out)))
  if not b: raise SystemExit(\"truncated\")
  h.update(b); total+=len(b); out.extend(b)
 return bytes(out)
def skip(n):
 global total
 while n:
  b=sys.stdin.buffer.read(min(1048576,n))
  if not b: raise SystemExit(\"truncated payload\")
  h.update(b); total+=len(b); n-=len(b)
hdr=readn(84)
print(\"magic\",hdr[:8].decode(),\"version\",struct.unpack(\"<I\",hdr[8:12])[0],\"generation\",struct.unpack(\"<Q\",hdr[76:84])[0])
sections=[]
while True:
 b=sys.stdin.buffer.read(8)
 if not b: break
 if len(b)"'!=8: raise SystemExit("partial section header")
 h.update(b); total+=8
 tag,n=struct.unpack("<II",b); sections.append((tag,n)); skip(n)
print("sections",sections)
print("expanded",total,"sha256",h.hexdigest())
'"'"
